import { SignalingMessage, ClientMessage } from './types.js';

export interface QueuedMessage {
  message: ClientMessage;
  timestamp: number;
  retries: number;
  id: string;
}

export interface MessageQueueConfig {
  maxSize: number;
  maxRetries: number;
  retryDelay: number;
}

export const DEFAULT_QUEUE_CONFIG: MessageQueueConfig = {
  maxSize: 100,
  maxRetries: 3,
  retryDelay: 1000,
};

export class MessageQueue extends EventTarget {
  private queue: QueuedMessage[] = [];
  private config: MessageQueueConfig;
  private processing = false;
  private sendCallback: ((message: ClientMessage) => Promise<boolean>) | null = null;

  constructor(config: Partial<MessageQueueConfig> = {}) {
    super();
    this.config = { ...DEFAULT_QUEUE_CONFIG, ...config };
  }

  setSendCallback(callback: (message: ClientMessage) => Promise<boolean>): void {
    this.sendCallback = callback;
  }

  enqueue(message: ClientMessage): boolean {
    if (this.queue.length >= this.config.maxSize) {
      this.dispatchEvent(new CustomEvent('queue-full', { detail: { message } }));
      return false;
    }

    const queued: QueuedMessage = {
      message,
      timestamp: Date.now(),
      retries: 0,
      id: this.generateId(),
    };

    this.queue.push(queued);
    this.dispatchEvent(new CustomEvent('enqueued', { detail: { message: queued } }));
    this.processQueue().catch(() => {
      // Error is handled inside processQueue
    });
    return true;
  }

  private async processQueue(): Promise<void> {
    if (this.processing || this.queue.length === 0 || !this.sendCallback) {
      return;
    }

    this.processing = true;

    try {
      while (this.queue.length > 0) {
        const queued = this.queue[0];
        if (!queued) break;
        let success = false;
        try {
          success = await this.sendCallback(queued.message);
        } catch (error) {
          this.dispatchEvent(new CustomEvent('send-error', { detail: { message: queued, error } }));
          success = false;
        }

        if (success) {
          this.queue.shift();
          this.dispatchEvent(new CustomEvent('sent', { detail: { message: queued } }));
        } else {
          queued.retries++;
          if (queued.retries >= this.config.maxRetries) {
            this.queue.shift();
            this.dispatchEvent(new CustomEvent('failed', { detail: { message: queued } }));
          } else {
            await this.delay(this.config.retryDelay * queued.retries);
          }
        }
      }
    } catch (error) {
      this.dispatchEvent(new CustomEvent('send-error', { detail: { error } }));
    } finally {
      this.processing = false;
      if (this.queue.length === 0) {
        this.dispatchEvent(new CustomEvent('queue-empty'));
      }
    }
  }

  private delay(ms: number): Promise<void> {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  private generateId(): string {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
      return crypto.randomUUID();
    }
    // Fallback for environments without crypto.randomUUID
    return `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
  }

  get size(): number {
    return this.queue.length;
  }

  get isEmpty(): boolean {
    return this.queue.length === 0;
  }

  get pendingMessages(): ReadonlyArray<QueuedMessage> {
    return [...this.queue];
  }

  clear(): void {
    const cleared = [...this.queue];
    this.queue = [];
    this.dispatchEvent(new CustomEvent('cleared', { detail: { messages: cleared } }));
  }

  remove(messageId: string): boolean {
    const index = this.queue.findIndex(m => m.id === messageId);
    if (index !== -1) {
      const [removed] = this.queue.splice(index, 1);
      this.dispatchEvent(new CustomEvent('removed', { detail: { message: removed } }));
      return true;
    }
    return false;
  }

  flush(timeoutMs = 30000): Promise<void> {
    return new Promise((resolve, reject) => {
      const timeoutTimer = setTimeout(() => {
        this.removeEventListener('queue-empty', handler);
        reject(new Error('Flush timeout'));
      }, timeoutMs);

      const handler = () => {
        if (this.isEmpty && !this.processing) {
          this.removeEventListener('queue-empty', handler);
          clearTimeout(timeoutTimer);
          resolve();
        }
      };
      this.addEventListener('queue-empty', handler);

      // Check immediately after listener is attached (in case processQueue completed synchronously)
      if (this.isEmpty && !this.processing) {
        this.removeEventListener('queue-empty', handler);
        clearTimeout(timeoutTimer);
        resolve();
        return;
      }

      this.processQueue().catch(() => {
        // Error is handled inside processQueue
      });
    });
  }
}

export function createMessageQueue(config?: Partial<MessageQueueConfig>): MessageQueue {
  return new MessageQueue(config);
}