import {
  SignalingMessage,
  ClientMessage,
  ServerMessage,
  JoinPayload,
  OfferPayload,
  AnswerPayload,
  IceCandidatePayload,
  MutePayload,
  VolumePayload,
  PositionPayload,
  PingPayload,
  ErrorPayload,
  Vec3,
  PongPayload,
  createJoinMessage,
  createOfferMessage,
  createAnswerMessage,
  createIceCandidateMessage,
  createMuteMessage,
  createVolumeMessage,
  createPositionMessage,
  createPingMessage,
  isServerMessage,
  isSignalingMessage,
} from './types.js';
import { MessageQueue, MessageQueueConfig } from './MessageQueue.js';

export interface SignalingClientConfig {
  url: string;
  reconnectAttempts: number;
  reconnectDelay: number;
  reconnectDelayMax: number;
  reconnectBackoffMultiplier: number;
  pingInterval: number;
  pongTimeout: number;
  messageQueue: Partial<MessageQueueConfig>;
}

export const DEFAULT_CLIENT_CONFIG: SignalingClientConfig = {
  url: '',
  reconnectAttempts: 10,
  reconnectDelay: 1000,
  reconnectDelayMax: 30000,
  reconnectBackoffMultiplier: 1.5,
  pingInterval: 25000,
  pongTimeout: 10000,
  messageQueue: {},
};

export type ConnectionState = 'disconnected' | 'connecting' | 'connected' | 'reconnecting' | 'failed';

export interface SignalingClientEvents {
  open: CustomEvent<{ url: string }>;
  close: CustomEvent<{ code: number; reason: string; wasClean: boolean }>;
  error: CustomEvent<{ error: Event | Error }>;
  message: CustomEvent<{ message: ServerMessage }>;
  statechange: CustomEvent<{ state: ConnectionState; previousState: ConnectionState }>;
  joined: CustomEvent<{ peerId: string; peers: Array<{ peerId: string; displayName: string }> }>;
  peerjoined: CustomEvent<{ peerId: string; displayName: string }>;
  peerleft: CustomEvent<{ peerId: string }>;
  offer: CustomEvent<{ from: string } & OfferPayload>;
  answer: CustomEvent<{ from: string } & AnswerPayload>;
  icecandidate: CustomEvent<{ from: string } & IceCandidatePayload>;
  mute: CustomEvent<{ from: string; muted: boolean }>;
  volume: CustomEvent<{ from: string; volume: number }>;
  position: CustomEvent<{ from: string; position: Vec3; rotation?: Vec3 }>;
  errorReceived: CustomEvent<{ code: string; message: string }>;
  pong: CustomEvent<{ rtt: number; serverTime: number }>;
  sendError: CustomEvent<{ message: ClientMessage; error: Error }>;
}

interface PendingPing {
  id: string;
  timestamp: number;
  timeoutTimer: ReturnType<typeof setTimeout>;
}

export class SignalingClient extends EventTarget {
  private ws: WebSocket | null = null;
  private config: SignalingClientConfig;
  private state: ConnectionState = 'disconnected';
  private reconnectAttempt = 0;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private pingTimer: ReturnType<typeof setInterval> | null = null;
  private messageQueue: MessageQueue;
  private pendingPings: Map<number, PendingPing> = new Map();
  private userInitiatedDisconnect = false;
  private isReconnecting = false;

  constructor(config: Partial<SignalingClientConfig> = {}) {
    super();
    this.config = { ...DEFAULT_CLIENT_CONFIG, ...config };
    this.messageQueue = new MessageQueue(this.config.messageQueue);
    this.messageQueue.setSendCallback(this.sendMessage.bind(this));
  }

  connect(): Promise<void> {
    return new Promise((resolve, reject) => {
      if (this.state === 'connected' || this.state === 'connecting' || this.state === 'reconnecting') {
        resolve();
        return;
      }

      this.userInitiatedDisconnect = false;
      this.setState('connecting');

      try {
        this.ws = new WebSocket(this.config.url);
        this.ws.binaryType = 'blob';

        this.ws.addEventListener('open', () => {
          this.reconnectAttempt = 0;
          this.isReconnecting = false;
          this.setState('connected');
          this.startPingInterval();
          this.messageQueue.flush().catch(() => {
            // Flush errors are handled by MessageQueue internally
          });
          this.dispatchEvent(new CustomEvent('open', { detail: { url: this.config.url } }));
          resolve();
        }, { once: true });

        this.ws.addEventListener('close', (event) => {
          this.stopPingInterval();
          this.clearAllPongTimers();
          const wasConnected = this.state === 'connected';
          this.setState('disconnected');
          this.dispatchEvent(new CustomEvent('close', {
            detail: { code: event.code, reason: event.reason, wasClean: event.wasClean }
          }));

          if (this.userInitiatedDisconnect) {
            this.reconnectAttempt = 0;
            this.isReconnecting = false;
            return;
          }

          if (wasConnected || this.reconnectAttempt > 0) {
            this.scheduleReconnect();
          } else {
            reject(new Error(`Connection failed: ${event.reason || 'Unknown error'}`));
          }
        }, { once: true });

        this.ws.addEventListener('error', (event) => {
          this.dispatchEvent(new CustomEvent('error', { detail: { error: event } }));
          if (this.state === 'connecting') {
            reject(new Error('WebSocket connection error'));
          }
        }, { once: true });

        this.ws.addEventListener('message', (event) => {
          this.handleMessage(event.data);
        });
      } catch (error) {
        this.setState('failed');
        reject(error);
      }
    });
  }

  disconnect(): void {
    this.userInitiatedDisconnect = true;
    this.stopPingInterval();
    this.clearAllPongTimers();
    this.clearReconnectTimer();
    this.messageQueue.clear();

    if (this.ws) {
      this.ws.close(1000, 'Client disconnect');
      this.ws = null;
    }

    this.setState('disconnected');
    this.reconnectAttempt = 0;
    this.isReconnecting = false;
  }

  private setState(newState: ConnectionState): void {
    const previousState = this.state;
    if (previousState !== newState) {
      this.state = newState;
      this.dispatchEvent(new CustomEvent('statechange', { detail: { state: newState, previousState } }));
    }
  }

  private scheduleReconnect(): void {
    this.clearReconnectTimer();

    if (this.isReconnecting) {
      return;
    }

    if (this.reconnectAttempt >= this.config.reconnectAttempts) {
      this.setState('failed');
      this.dispatchEvent(new CustomEvent('error', {
        detail: { error: new Error('Max reconnection attempts reached') }
      }));
      return;
    }

    this.isReconnecting = true;
    this.setState('reconnecting');
    this.reconnectAttempt++;

    const delay = Math.min(
      this.config.reconnectDelay * Math.pow(this.config.reconnectBackoffMultiplier, this.reconnectAttempt - 1),
      this.config.reconnectDelayMax
    );

    this.reconnectTimer = setTimeout(async () => {
      this.isReconnecting = false;
      try {
        await this.connect();
      } catch {
        // Reconnection failed, will retry via onclose
      }
    }, delay);
  }

  private clearReconnectTimer(): void {
    if (this.reconnectTimer) {
      clearTimeout(this.reconnectTimer);
      this.reconnectTimer = null;
    }
  }

  private startPingInterval(): void {
    this.stopPingInterval();
    this.pingTimer = setInterval(() => {
      this.sendPing();
    }, this.config.pingInterval);
  }

  private stopPingInterval(): void {
    if (this.pingTimer) {
      clearInterval(this.pingTimer);
      this.pingTimer = null;
    }
  }

  private generatePingId(): string {
    if (typeof crypto !== 'undefined' && crypto.randomUUID) {
      return crypto.randomUUID();
    }
    return `${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
  }

  private sendPing(): void {
    const timestamp = Date.now();
    const pingMessage = createPingMessage();
    // Overwrite the timestamp to ensure it matches our recorded value
    (pingMessage.payload as PingPayload).timestamp = timestamp;
    const pingId = this.generatePingId();

    const timeoutTimer = setTimeout(() => {
      this.handlePingTimeout(pingId);
    }, this.config.pongTimeout);

    this.pendingPings.set(timestamp, { id: pingId, timestamp, timeoutTimer });

    this.sendMessage(pingMessage).catch(() => {
      this.pendingPings.delete(timestamp);
      clearTimeout(timeoutTimer);
    });
  }

  private clearAllPongTimers(): void {
    for (const pending of this.pendingPings.values()) {
      clearTimeout(pending.timeoutTimer);
    }
    this.pendingPings.clear();
  }

  private handlePingTimeout(pingId: string): void {
    // Find by ID since we can't easily reverse-lookup by timestamp
    for (const [timestamp, pending] of this.pendingPings.entries()) {
      if (pending.id === pingId) {
        this.pendingPings.delete(timestamp);
        this.dispatchEvent(new CustomEvent('error', {
          detail: { error: new Error('Pong timeout') }
        }));
        if (this.ws) {
          this.ws.close(1000, 'Pong timeout');
        }
        break;
      }
    }
  }

  private async sendMessage(message: ClientMessage): Promise<boolean> {
    if (!this.ws || this.ws.readyState !== WebSocket.OPEN) {
      this.dispatchEvent(new CustomEvent('sendError', {
        detail: { message, error: new Error('WebSocket not open') }
      }));
      return false;
    }

    try {
      const data = JSON.stringify(message);
      this.ws.send(data);
      return true;
    } catch (error) {
      this.dispatchEvent(new CustomEvent('sendError', {
        detail: { message, error: error instanceof Error ? error : new Error(String(error)) }
      }));
      return false;
    }
  }

  private handleMessage(data: string | ArrayBuffer): void {
    let message: unknown;

    try {
      if (typeof data === 'string') {
        message = JSON.parse(data);
      } else {
        const decoder = new TextDecoder();
        message = JSON.parse(decoder.decode(data));
      }
    } catch {
      this.dispatchEvent(new CustomEvent('error', {
        detail: { error: new Error('Failed to parse message') }
      }));
      return;
    }

    if (!isSignalingMessage(message)) {
      this.dispatchEvent(new CustomEvent('error', {
        detail: { error: new Error('Invalid message format') }
      }));
      return;
    }

    if (!isServerMessage(message)) {
      return;
    }

    this.dispatchEvent(new CustomEvent('message', { detail: { message } }));

    switch (message.type) {
      case 'joined':
        this.dispatchEvent(new CustomEvent('joined', { detail: message.payload }));
        break;
      case 'peer-joined':
        this.dispatchEvent(new CustomEvent('peerjoined', { detail: message.payload }));
        break;
      case 'peer-left':
        this.dispatchEvent(new CustomEvent('peerleft', { detail: message.payload }));
        break;
      case 'offer':
        this.dispatchEvent(new CustomEvent('offer', { detail: { from: message.from ?? 'unknown', ...message.payload } }));
        break;
      case 'answer':
        this.dispatchEvent(new CustomEvent('answer', { detail: { from: message.from ?? 'unknown', ...message.payload } }));
        break;
      case 'ice-candidate':
        this.dispatchEvent(new CustomEvent('icecandidate', { detail: { from: message.from ?? 'unknown', ...message.payload } }));
        break;
      case 'mute':
        this.dispatchEvent(new CustomEvent('mute', { detail: { from: message.from ?? 'unknown', ...message.payload } }));
        break;
      case 'volume':
        this.dispatchEvent(new CustomEvent('volume', { detail: { from: message.from ?? 'unknown', ...message.payload } }));
        break;
      case 'position':
        this.dispatchEvent(new CustomEvent('position', { detail: { from: message.from ?? 'unknown', ...message.payload } }));
        break;
      case 'error':
        this.dispatchEvent(new CustomEvent('errorReceived', { detail: message.payload }));
        break;
      case 'pong':
        this.handlePong(message.payload);
        break;
    }
  }

  private handlePong(payload: PongPayload): void {
    const pending = this.pendingPings.get(payload.timestamp);

    if (pending) {
      this.pendingPings.delete(payload.timestamp);
      clearTimeout(pending.timeoutTimer);
      const rtt = Date.now() - pending.timestamp;
      this.dispatchEvent(new CustomEvent('pong', { detail: { rtt, serverTime: payload.serverTime } }));
    }
  }

  async join(payload: JoinPayload): Promise<void> {
    const message = createJoinMessage(payload);
    await this.sendOrQueue(message);
  }

  async sendOffer(payload: OfferPayload): Promise<void> {
    const message = createOfferMessage(payload);
    await this.sendOrQueue(message);
  }

  async sendAnswer(payload: AnswerPayload): Promise<void> {
    const message = createAnswerMessage(payload);
    await this.sendOrQueue(message);
  }

  async sendIceCandidate(payload: IceCandidatePayload): Promise<void> {
    const message = createIceCandidateMessage(payload);
    await this.sendOrQueue(message);
  }

  async sendMute(payload: MutePayload): Promise<void> {
    const message = createMuteMessage(payload);
    await this.sendOrQueue(message);
  }

  async sendVolume(payload: VolumePayload): Promise<void> {
    const message = createVolumeMessage(payload);
    await this.sendOrQueue(message);
  }

  async sendPosition(payload: PositionPayload): Promise<void> {
    const message = createPositionMessage(payload);
    await this.sendOrQueue(message);
  }

  private async sendOrQueue(message: ClientMessage): Promise<void> {
    if (this.state === 'connected') {
      const sent = await this.sendMessage(message);
      if (!sent) {
        this.messageQueue.enqueue(message);
      }
    } else {
      this.messageQueue.enqueue(message);
    }
  }

  getState(): ConnectionState {
    return this.state;
  }

  getQueueSize(): number {
    return this.messageQueue.size;
  }

  isConnected(): boolean {
    return this.state === 'connected';
  }
}

export function createSignalingClient(config: Partial<SignalingClientConfig>): SignalingClient {
  return new SignalingClient(config);
}
