export interface Vec3 {
  x: number;
  y: number;
  z: number;
}

export function createVec3(x: number, y: number, z: number): Vec3 {
  return { x, y, z };
}

export function vec3Equals(a: Vec3, b: Vec3, epsilon = 1e-6): boolean {
  return (
    Math.abs(a.x - b.x) < epsilon &&
    Math.abs(a.y - b.y) < epsilon &&
    Math.abs(a.z - b.z) < epsilon
  );
}

export function vec3Distance(a: Vec3, b: Vec3): number {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  const dz = a.z - b.z;
  return Math.sqrt(dx * dx + dy * dy + dz * dz);
}

export function vec3Clone(v: Vec3): Vec3 {
  return { x: v.x, y: v.y, z: v.z };
}

export type SignalingMessageType =
  | 'join'
  | 'joined'
  | 'peer-joined'
  | 'peer-left'
  | 'offer'
  | 'answer'
  | 'ice-candidate'
  | 'mute'
  | 'volume'
  | 'position'
  | 'error'
  | 'ping'
  | 'pong';

export interface BaseSignalingMessage<T extends SignalingMessageType, P> {
  type: T;
  payload: P;
  from?: string;
  to?: string;
  roomId?: string;
  timestamp?: number;
}

export interface JoinPayload {
  token: string;
  roomId: string;
  displayName: string;
}

export interface JoinedPayload {
  peerId: string;
  peers: Array<{
    peerId: string;
    displayName: string;
  }>;
}

export interface PeerJoinedPayload {
  peerId: string;
  displayName: string;
}

export interface PeerLeftPayload {
  peerId: string;
}

export interface OfferPayload {
  roomId: string;
  to: string;
  sdp: string;
}

export interface AnswerPayload {
  roomId: string;
  to: string;
  sdp: string;
}

export interface IceCandidatePayload {
  roomId: string;
  to: string;
  candidate: string;
  sdpMid: string;
  sdpMLineIndex: number;
}

export interface MutePayload {
  muted: boolean;
}

export interface VolumePayload {
  volume: number;
}

export interface PositionPayload {
  position: Vec3;
  rotation?: Vec3;
}

export interface ErrorPayload {
  code: string;
  message: string;
}

export interface PingPayload {
  timestamp: number;
}

export interface PongPayload {
  timestamp: number;
  serverTime: number;
}

export type ClientMessage =
  | BaseSignalingMessage<'join', JoinPayload>
  | BaseSignalingMessage<'offer', OfferPayload>
  | BaseSignalingMessage<'answer', AnswerPayload>
  | BaseSignalingMessage<'ice-candidate', IceCandidatePayload>
  | BaseSignalingMessage<'mute', MutePayload>
  | BaseSignalingMessage<'volume', VolumePayload>
  | BaseSignalingMessage<'position', PositionPayload>
  | BaseSignalingMessage<'ping', PingPayload>;

export type ServerMessage =
  | BaseSignalingMessage<'joined', JoinedPayload>
  | BaseSignalingMessage<'peer-joined', PeerJoinedPayload>
  | BaseSignalingMessage<'peer-left', PeerLeftPayload>
  | BaseSignalingMessage<'offer', OfferPayload>
  | BaseSignalingMessage<'answer', AnswerPayload>
  | BaseSignalingMessage<'ice-candidate', IceCandidatePayload>
  | BaseSignalingMessage<'mute', MutePayload>
  | BaseSignalingMessage<'volume', VolumePayload>
  | BaseSignalingMessage<'position', PositionPayload>
  | BaseSignalingMessage<'error', ErrorPayload>
  | BaseSignalingMessage<'pong', PongPayload>;

export type SignalingMessage = ClientMessage | ServerMessage;

export function isVec3(value: unknown): value is Vec3 {
  return (
    typeof value === 'object' &&
    value !== null &&
    'x' in value &&
    'y' in value &&
    'z' in value &&
    typeof (value as Record<string, unknown>)['x'] === 'number' &&
    typeof (value as Record<string, unknown>)['y'] === 'number' &&
    typeof (value as Record<string, unknown>)['z'] === 'number'
  );
}

function isOptionalString(value: unknown): boolean {
  return value === undefined || typeof value === 'string';
}

function isOptionalNumber(value: unknown): boolean {
  return value === undefined || typeof value === 'number';
}

function validateBaseFields(msg: Record<string, unknown>): boolean {
  return (
    isOptionalString(msg['from']) &&
    isOptionalString(msg['to']) &&
    isOptionalString(msg['roomId']) &&
    isOptionalNumber(msg['timestamp'])
  );
}

export function isJoinPayload(value: unknown): value is JoinPayload {
  return (
    typeof value === 'object' &&
    value !== null &&
    'token' in value &&
    'roomId' in value &&
    'displayName' in value &&
    typeof (value as Record<string, unknown>)['token'] === 'string' &&
    typeof (value as Record<string, unknown>)['roomId'] === 'string' &&
    typeof (value as Record<string, unknown>)['displayName'] === 'string'
  );
}

export function isJoinedPayload(value: unknown): value is JoinedPayload {
  return (
    typeof value === 'object' &&
    value !== null &&
    'peerId' in value &&
    'peers' in value &&
    typeof (value as Record<string, unknown>)['peerId'] === 'string' &&
    Array.isArray((value as Record<string, unknown>)['peers']) &&
    ((value as Record<string, unknown>)['peers'] as unknown[]).every(
      p => typeof p === 'object' && p !== null && 'peerId' in p && 'displayName' in p
    )
  );
}

export function isPeerJoinedPayload(value: unknown): value is PeerJoinedPayload {
  return (
    typeof value === 'object' &&
    value !== null &&
    'peerId' in value &&
    'displayName' in value &&
    typeof (value as Record<string, unknown>)['peerId'] === 'string' &&
    typeof (value as Record<string, unknown>)['displayName'] === 'string'
  );
}

export function isPeerLeftPayload(value: unknown): value is PeerLeftPayload {
  return (
    typeof value === 'object' &&
    value !== null &&
    'peerId' in value &&
    typeof (value as Record<string, unknown>)['peerId'] === 'string'
  );
}

export function isOfferPayload(value: unknown): value is OfferPayload {
  return (
    typeof value === 'object' &&
    value !== null &&
    'sdp' in value &&
    'to' in value &&
    typeof (value as Record<string, unknown>)['roomId'] === 'string' &&
    typeof (value as Record<string, unknown>)['to'] === 'string' &&
    typeof (value as Record<string, unknown>)['sdp'] === 'string'
  );
}

export function isAnswerPayload(value: unknown): value is AnswerPayload {
  return isOfferPayload(value);
}

export function isIceCandidatePayload(value: unknown): value is IceCandidatePayload {
  return (
    typeof value === 'object' &&
    value !== null &&
    'candidate' in value &&
    'roomId' in value &&
    'to' in value &&
    'sdpMid' in value &&
    'sdpMLineIndex' in value &&
    typeof (value as Record<string, unknown>)['roomId'] === 'string' &&
    typeof (value as Record<string, unknown>)['to'] === 'string' &&
    typeof (value as Record<string, unknown>)['candidate'] === 'string' &&
    typeof (value as Record<string, unknown>)['sdpMid'] === 'string' &&
    typeof (value as Record<string, unknown>)['sdpMLineIndex'] === 'number'
  );
}

export function isMutePayload(value: unknown): value is MutePayload {
  return (
    typeof value === 'object' &&
    value !== null &&
    'muted' in value &&
    typeof (value as Record<string, unknown>)['muted'] === 'boolean'
  );
}

export function isVolumePayload(value: unknown): value is VolumePayload {
  return (
    typeof value === 'object' &&
    value !== null &&
    'volume' in value &&
    typeof (value as Record<string, unknown>)['volume'] === 'number'
  );
}

export function isPositionPayload(value: unknown): value is PositionPayload {
  return (
    typeof value === 'object' &&
    value !== null &&
    'position' in value &&
    isVec3((value as Record<string, unknown>)['position']) &&
    (!('rotation' in value) || (value as Record<string, unknown>)['rotation'] === undefined || isVec3((value as Record<string, unknown>)['rotation']))
  );
}

export function isErrorPayload(value: unknown): value is ErrorPayload {
  return (
    typeof value === 'object' &&
    value !== null &&
    'code' in value &&
    'message' in value &&
    typeof (value as Record<string, unknown>)['code'] === 'string' &&
    typeof (value as Record<string, unknown>)['message'] === 'string'
  );
}

export function isPingPayload(value: unknown): value is PingPayload {
  return (
    typeof value === 'object' &&
    value !== null &&
    'timestamp' in value &&
    typeof (value as Record<string, unknown>)['timestamp'] === 'number'
  );
}

export function isPongPayload(value: unknown): value is PongPayload {
  return (
    typeof value === 'object' &&
    value !== null &&
    'timestamp' in value &&
    'serverTime' in value &&
    typeof (value as Record<string, unknown>)['timestamp'] === 'number' &&
    typeof (value as Record<string, unknown>)['serverTime'] === 'number'
  );
}

function validateMessage<T extends SignalingMessageType, P>(
  msg: unknown,
  type: T,
  payloadValidator: (value: unknown) => value is P
): msg is BaseSignalingMessage<T, P> {
  return (
    typeof msg === 'object' &&
    msg !== null &&
    'type' in msg &&
    (msg as Record<string, unknown>)['type'] === type &&
    'payload' in msg &&
    payloadValidator((msg as Record<string, unknown>)['payload']) &&
    validateBaseFields(msg as Record<string, unknown>)
  );
}

export function isClientMessage(msg: unknown): msg is ClientMessage {
  if (typeof msg !== 'object' || msg === null || !('type' in msg) || !('payload' in msg)) {
    return false;
  }
  const type = (msg as Record<string, unknown>)['type'] as string;
  const payload = (msg as Record<string, unknown>)['payload'];

  switch (type) {
    case 'join':
      return validateMessage(msg, 'join', isJoinPayload);
    case 'offer':
      return validateMessage(msg, 'offer', isOfferPayload);
    case 'answer':
      return validateMessage(msg, 'answer', isAnswerPayload);
    case 'ice-candidate':
      return validateMessage(msg, 'ice-candidate', isIceCandidatePayload);
    case 'mute':
      return validateMessage(msg, 'mute', isMutePayload);
    case 'volume':
      return validateMessage(msg, 'volume', isVolumePayload);
    case 'position':
      return validateMessage(msg, 'position', isPositionPayload);
    case 'ping':
      return validateMessage(msg, 'ping', isPingPayload);
    default:
      return false;
  }
}

export function isServerMessage(msg: unknown): msg is ServerMessage {
  if (typeof msg !== 'object' || msg === null || !('type' in msg) || !('payload' in msg)) {
    return false;
  }
  const type = (msg as Record<string, unknown>)['type'] as string;
  const payload = (msg as Record<string, unknown>)['payload'];

  switch (type) {
    case 'joined':
      return validateMessage(msg, 'joined', isJoinedPayload);
    case 'peer-joined':
      return validateMessage(msg, 'peer-joined', isPeerJoinedPayload);
    case 'peer-left':
      return validateMessage(msg, 'peer-left', isPeerLeftPayload);
    case 'offer':
      return validateMessage(msg, 'offer', isOfferPayload);
    case 'answer':
      return validateMessage(msg, 'answer', isAnswerPayload);
    case 'ice-candidate':
      return validateMessage(msg, 'ice-candidate', isIceCandidatePayload);
    case 'mute':
      return validateMessage(msg, 'mute', isMutePayload);
    case 'volume':
      return validateMessage(msg, 'volume', isVolumePayload);
    case 'position':
      return validateMessage(msg, 'position', isPositionPayload);
    case 'error':
      return validateMessage(msg, 'error', isErrorPayload);
    case 'pong':
      return validateMessage(msg, 'pong', isPongPayload);
    default:
      return false;
  }
}

export function isSignalingMessage(msg: unknown): msg is SignalingMessage {
  return isClientMessage(msg) || isServerMessage(msg);
}

export function createJoinMessage(payload: JoinPayload): ClientMessage {
  return { type: 'join', payload, timestamp: Date.now() };
}

export function createOfferMessage(payload: OfferPayload): ClientMessage {
  return { type: 'offer', payload, timestamp: Date.now() };
}

export function createAnswerMessage(payload: AnswerPayload): ClientMessage {
  return { type: 'answer', payload, timestamp: Date.now() };
}

export function createIceCandidateMessage(payload: IceCandidatePayload): ClientMessage {
  return { type: 'ice-candidate', payload, timestamp: Date.now() };
}

export function createMuteMessage(payload: MutePayload): ClientMessage {
  return { type: 'mute', payload, timestamp: Date.now() };
}

export function createVolumeMessage(payload: VolumePayload): ClientMessage {
  return { type: 'volume', payload, timestamp: Date.now() };
}

export function createPositionMessage(payload: PositionPayload): ClientMessage {
  return { type: 'position', payload, timestamp: Date.now() };
}

export function createPingMessage(): ClientMessage {
  return { type: 'ping', payload: { timestamp: Date.now() }, timestamp: Date.now() };
}
